'use strict';
const acsView={devices:[],tasks:[],faults:[],config:null,timer:null,filter:'all'};
function acsClockNotice(){const device=acsView.devices.find(d=>Math.abs(d.clockSkewSeconds||0)>60);return device?notice('Clock difference detected',`The ACS and dashboard clocks differ by about ${Math.round(Math.abs(device.clockSkewSeconds)/60)} minutes. Online status and check-in age use the ACS clock.`):'';}
function acsCheckIn(device){const seconds=device.lastInformAgeSeconds;return h(stamp(device.lastInform))+(Number.isFinite(seconds)?`<small>${seconds < -60?'Ahead of ACS time':Math.max(0,seconds)<60?Math.max(0,seconds)+' seconds ago (ACS clock)':Math.floor(seconds/60)+' minutes ago (ACS clock)'}</small>`:'');}
async function renderAcs(){
 clearTimeout(acsView.timer);try{acsView.config=await api('acs/config');acsView.tasks=await api('acs/tasks');acsView.devices=acsView.config?await api('acs/devices'):[];acsView.faultError='';if(acsView.config)try{acsView.faults=await api('acs/faults');}catch(error){acsView.faults=[];acsView.faultError=error.message;}else acsView.faults=[];if(state.page!=='tr069')return;
 const total=acsView.devices.length,online=acsView.devices.filter(d=>d.online).length,offline=total-online,rx=acsView.devices.filter(d=>d.rxPower!==null&&d.rxPower!==undefined&&Number.isFinite(Number(d.rxPower))).map(d=>Number(d.rxPower)).sort((a,b)=>a-b),median=rx.length?rx[Math.floor(rx.length/2)]:null,onts=acsView.devices.filter(d=>/ont|onu|gpon|epon|fiber/i.test([d.model,d.productClass,d.accessType].join(' '))).length;
 const stat=(name,value,foot)=>`<article class="card stat"><div class="stat-heading">${name}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`;
 const dist=(title,key)=>{const counts={};for(const d of acsView.devices){const v=d[key];if(v!==null&&v!==undefined&&String(v).trim())counts[String(v)]=(counts[String(v)]||0)+1;}const rows=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,6);return `<section class="card" style="padding:17px 20px"><h3 style="margin:0 0 12px">${title}</h3>${rows.length?rows.map(([label,count])=>`<div style="display:flex;justify-content:space-between;padding:7px 0;border-top:1px solid var(--border);font-size:11px"><span>${h(label)}</span><strong>${count}</strong></div>`).join(''):'<p class="muted">No ACS values reported yet</p>'}</section>`;};
 $('#main').innerHTML=heading('TR-069','Live customer equipment monitoring through your independent GenieACS service.',state.session.user.role==='admin'?'<button class="button secondary" data-acs-config>ACS Settings</button>':'')+(acsView.config?notice('Connected to your independent ACS',(acsView.config.acsUrl?`CPE ACS URL: <strong>${h(acsView.config.acsUrl)}</strong><br>`:'')+'Inventory and fault data refresh every 30 seconds. Online threshold: '+acsView.config.onlineMinutes+' minutes. Credentials remain on the server.'):notice('ACS service connection required','Connect a running GenieACS NBI endpoint. The ACS host, CWMP listener, database, and CPE reachability must be configured first.',true))+acsClockNotice()+(acsView.faultError?notice('ACS fault log unavailable',h(acsView.faultError)): '')+`<section class="stats">${stat('ACS devices',total,'All devices known to GenieACS')}${stat('Online',online,`${total?Math.round(online/total*100):0}% informed within ${acsView.config?.onlineMinutes||15} min`)}${stat('Offline',offline,'No recent check-in')}${stat('Open ACS faults',acsView.faults.length,'Faults read directly from GenieACS')}</section><section class="card" style="padding:20px;margin-bottom:20px"><div class="card-header" style="padding:0"><div><h2>Optical signal overview</h2><p>Values appear when the CPE reports supported optical parameters to the ACS.</p></div><span class="button secondary">${onts} likely ONTs · Median RX ${median===null?'—':h(median)+' dBm'}</span></div><div class="settings-grid" style="margin-top:18px">${dist('RX power distribution','rxPower')}${dist('Temperature distribution','temperature')}${dist('Vendor distribution','manufacturer')}${dist('Model / product class distribution','productClass')}</div></section><section class="card"><div class="table-toolbar"><input id="acs-query" type="search" placeholder="Search serial, model or device ID…" aria-label="Search TR-069 devices"><span>${online} online / ${total} total</span><button class="button secondary" data-acs-reload>${icon('refresh',14)} Sync from ACS</button></div><div class="filter-bar" style="padding-top:0"><button class="button secondary" data-acs-filter="all" aria-pressed="${acsView.filter==='all'}">All (${total})</button><button class="button secondary" data-acs-filter="online" aria-pressed="${acsView.filter==='online'}">Online (${online})</button><button class="button secondary" data-acs-filter="offline" aria-pressed="${acsView.filter==='offline'}">Offline (${offline})</button></div><div id="acs-device-list"></div></section><section class="card" style="margin-top:20px"><div class="card-header"><h2>Open ACS faults</h2></div>${table(['DEVICE','FAULT','CODE','RETRIES','REPORTED'],acsView.faults.slice(0,50),f=>`<tr><td>${h(f.deviceId)}</td><td>${h(f.message)}</td><td>${h(f.code||'—')}</td><td>${h(f.retries??'—')}</td><td>${h(stamp(f.timestamp))}</td></tr>`,'No open faults reported by GenieACS')}<p style="padding:0 20px 16px;color:var(--muted);font-size:10px">Faults are read from the ACS and do not establish whether customer internet service is working.</p></section><section class="card" style="margin-top:20px"><div class="card-header"><h2>Device operations</h2></div>${table(['DEVICE','ACTION','STATUS','DATE','RECONCILIATION'],acsView.tasks.slice(0,50),t=>`<tr><td>${h(t.deviceId)}</td><td>${h(t.action)}</td><td>${badge(t.status)}</td><td>${h(stamp(t.created))}</td><td>${['Queued','Uncertain'].includes(t.status)&&NetworkPermissions.equipment(state.session.user.role)?`<button class="button secondary" data-acs-reconcile="${t.id}">Reconcile after checking</button>`:h(t.error||'—')}</td></tr>`)}</section>`;paintAcsList();$('#acs-query').oninput=paintAcsList;
 }catch(error){if(state.page!=='tr069')return;$('#main').innerHTML=heading('TR-069','Independent GenieACS connection',state.session.user.role==='admin'?'<button class="button secondary" data-acs-config>Configure ACS</button>':'')+notice('ACS unavailable',h(error.message),true);}
 if(state.page==='tr069')acsView.timer=setTimeout(()=>{if(state.page==='tr069'&&!document.hidden&&!$('dialog[open]')&&!document.activeElement?.closest('#acs-query'))renderAcs();},30000);
}
function paintAcsList(){const q=$('#acs-query')?.value.toLowerCase()||'',items=acsView.devices.filter(d=>(acsView.filter==='all'||(acsView.filter==='online')===d.online)&&[d.id,d.serial,d.model,d.manufacturer,d.productClass].join(' ').toLowerCase().includes(q));$('#acs-device-list').innerHTML=table(['DEVICE / SERIAL','MODEL','STATUS','RX / TEMP','LAST CHECK-IN','ACTIONS'],items,d=>`<tr><td><button class="link-button" data-acs-device="${h(d.id)}">${h(d.serial||d.id)}</button><small>${h(d.id)}</small></td><td>${h(d.manufacturer)} ${h(d.model)}</td><td>${badge(d.online?'online':'offline')}</td><td>${d.rxPower==null?'—':h(d.rxPower)+' dBm'} / ${d.temperature==null?'—':h(d.temperature)+' °C'}</td><td>${acsCheckIn(d)}</td><td><button class="button secondary" data-acs-device="${h(d.id)}">Manage</button></td></tr>`,'No ACS devices match this filter');}
function configureAcs(){const current=acsView.config||{};$('#editor-title').textContent=current.origin?'ACS settings':'Connect your independent GenieACS';$('#editor-description').textContent='The dashboard tests the NBI endpoint before saving. The CWMP service, database, device authentication and network reachability must already be configured on your ACS host.';$('#editor-fields').innerHTML=`<label>GenieACS NBI origin<input name="origin" type="url" required value="${h(current.origin||'http://127.0.0.1:7557')}" placeholder="https://acs-api.example.com"></label><label>Public HTTPS ACS URL for CPEs (optional)<input name="acsUrl" type="url" value="${h(current.acsUrl||'')}" placeholder="https://acs.example.com/"></label><label>Device online timeout (minutes)<input name="onlineMinutes" type="number" required min="1" max="1440" value="${current.onlineMinutes||15}"></label><label>NBI reverse-proxy username<input name="username" autocomplete="off"></label><label>NBI reverse-proxy password<input name="password" type="password" autocomplete="off"></label><p class="field-note">Leave both credential fields blank to keep the current credentials. A remote NBI requires verified HTTPS and authentication. These are separate from CPE connection-request credentials.</p>`;$('#editor-error').textContent='';$('#editor').showModal();$('#editor-form').onsubmit=async event=>{event.preventDefault();const button=$('[type=submit]',event.currentTarget);button.disabled=true;try{acsView.config=await api('acs/config','POST',Object.fromEntries(new FormData(event.currentTarget)));$('#editor-form').reset();$('#editor').close();await renderAcs();toast('Independent ACS settings verified');}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};}
async function showAcsDevice(id){showDetails('TR-069 device','<p>Reading ACS observations…</p>');try{const d=await api('acs/devices/'+encodeURIComponent(id)),edit=NetworkPermissions.equipment(state.session.user.role),mikrotik=/mikrotik|routeros/i.test(`${d.manufacturer} ${d.model} ${d.productClass}`),canChange=edit&&!mikrotik;showDetails(d.serial||d.id,`<p>${h(d.manufacturer)} ${h(d.model)} · ${badge(d.online?'online':'offline')}</p><div class="detail-grid"><div><small>Software / hardware</small><strong>${h(d.software||'—')} / ${h(d.hardware||'—')}</strong></div><div><small>Uptime (seconds)</small><strong>${h(d.uptime??'—')}</strong></div><div><small>RX / TX optical power</small><strong>${d.rxPower==null?'—':h(d.rxPower)+' dBm'} / ${d.txPower==null?'—':h(d.txPower)+' dBm'}</strong></div><div><small>Temperature / access type</small><strong>${d.temperature==null?'—':h(d.temperature)+' °C'} / ${h(d.accessType||'—')}</strong></div><div><small>Product class / PON status</small><strong>${h(d.productClass||'—')} / ${h(d.ponMode||'—')}</strong></div><div><small>WAN IP / last check-in</small><strong style="font-size:13px">${h(d.wanIp||'—')} · ${h(stamp(d.lastInform))}</strong></div></div>${edit?`<div class="setup-actions"><button class="button secondary" data-acs-action="refresh" data-cpe="${h(id)}">Refresh parameters</button></div>`:''}${mikrotik?notice('MikroTik access is read-only','Network Hub blocks configuration and reboot tasks for MikroTik devices.'):''}<h3>Observed Wi-Fi networks</h3>${table(['NETWORK','SSID','ENABLED','ACTIONS'],d.wifi,w=>`<tr><td>${h(w.id)}</td><td>${h(w.ssid)}</td><td>${w.enabled===null?'Not observed':w.enabled?'Yes':'No'}</td><td>${canChange?`<button class="button secondary" data-acs-wifi="${h(w.id)}" data-cpe="${h(id)}">Edit Wi-Fi</button>`:''}</td></tr>`,'No supported Wi-Fi parameters observed')}<p style="margin-top:15px">Queued requests run at the next successful device check-in. An ACS execution receipt confirms its task result; physical device behavior still needs verification.</p>`);}catch(error){showDetails('TR-069 device',notice('Could not read the device',h(error.message),true));}}
async function editAcsWifi(id,networkId){const d=await api('acs/devices/'+encodeURIComponent(id)),wifi=d.wifi.find(w=>w.id===networkId);if(!wifi)return toast('Refresh the observed Wi-Fi networks first');$('#detail-dialog').close();$('#editor-title').textContent='Edit Wi-Fi — '+(d.serial||id);$('#editor-description').textContent='Send changes to the observed CPE network '+networkId+'. Existing passwords are not read or displayed.';$('#editor-fields').innerHTML=`<label>SSID<input name="ssid" required maxlength="32" value="${h(wifi.ssid)}"></label><label>New Wi-Fi password (leave blank to keep it)<input name="password" type="password" minlength="8" maxlength="63" autocomplete="new-password" ${wifi.passwordSupported?'':'disabled'}></label><label class="check-label"><input name="enabled" type="checkbox" ${wifi.enabled?'checked':''} ${wifi.enabled===null?'disabled':''}> Wi-Fi enabled${wifi.enabled===null?' (state not observed; left unchanged)':''}</label>`;$('#editor-error').textContent='';$('#editor').showModal();$('#editor-form').onsubmit=async event=>{event.preventDefault();const button=$('[type=submit]',event.currentTarget);button.disabled=true;try{const input=new FormData(event.currentTarget),receipt=await api('acs/devices/'+encodeURIComponent(id)+'/wifi','POST',{networkId,ssid:input.get('ssid'),password:input.get('password')||'',...(wifi.enabled===null?{}:{enabled:input.has('enabled')})});$('#editor-form').reset();$('#editor').close();await renderAcs();toast(receipt.status==='Queued'?'Wi-Fi change queued for the CPE':receipt.status);}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};}
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
 if(button.dataset.acsFilter){acsView.filter=button.dataset.acsFilter;document.querySelectorAll('[data-acs-filter]').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.acsFilter===acsView.filter)));paintAcsList();}
 if(button.hasAttribute('data-acs-config'))configureAcs();if(button.hasAttribute('data-acs-reload'))await renderAcs();if(button.dataset.acsDevice)await showAcsDevice(button.dataset.acsDevice);if(button.dataset.acsWifi)await editAcsWifi(button.dataset.cpe,button.dataset.acsWifi);
 if(button.dataset.acsAction){if(button.dataset.acsAction==='reboot'&&!confirm('Reboot this customer device? Its connection will be interrupted.'))return;button.disabled=true;const receipt=await api('acs/devices/'+encodeURIComponent(button.dataset.cpe)+'/'+button.dataset.acsAction,'POST',{});$('#detail-dialog').close();await renderAcs();toast(receipt.status==='Queued'?'Request queued for the next CPE check-in':receipt.status);}
 if(button.dataset.acsReconcile){if(!confirm('Confirm you have checked this operation on the ACS and device. This closes local tracking; it does not cancel or retry the ACS task.'))return;await api('acs/tasks/'+button.dataset.acsReconcile+'/reconcile','POST',{checked:true});await renderAcs();toast('Operation reconciliation recorded');}
 }catch(error){toast(error.message);}finally{if(button.dataset.acsAction)button.disabled=false;}});
